DROP TABLE IF EXISTS `sys_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `user_name` varchar(64) NOT NULL COMMENT '登录账号(租户内唯一)',
  `nick_name` varchar(50) NOT NULL COMMENT '姓名',
  `emp_no` varchar(64) DEFAULT NULL COMMENT '工号',
  `password` varchar(128) NOT NULL COMMENT '密码(BCrypt加密)',
  `company_id` bigint DEFAULT NULL COMMENT '所属公司ID',
  `dept_id` bigint DEFAULT NULL COMMENT '所属部门ID',
  `post_id` bigint DEFAULT NULL COMMENT '主岗位ID',
  `phone` varchar(30) DEFAULT NULL COMMENT '手机号',
  `email` varchar(100) DEFAULT NULL COMMENT '邮箱',
  `sex` varchar(10) DEFAULT 'UNKNOWN' COMMENT '性别:MALE/FEMALE/UNKNOWN',
  `avatar` varchar(500) DEFAULT NULL COMMENT '头像地址',
  `id_card` varchar(64) DEFAULT NULL COMMENT '身份证号(加密存储)',
  `bank_name` varchar(200) DEFAULT NULL COMMENT '个人收款开户行',
  `bank_account` varchar(64) DEFAULT NULL COMMENT '个人收款账号(加密存储)',
  `is_admin` tinyint NOT NULL DEFAULT '0' COMMENT '是否租户管理员:0否 1是(租户内最高权限)',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL正常/DISABLED停用/LOCKED锁定',
  `pwd_update_time` datetime DEFAULT NULL COMMENT '最后改密时间',
  `login_ip` varchar(64) DEFAULT NULL COMMENT '最后登录IP',
  `login_time` datetime DEFAULT NULL COMMENT '最后登录时间',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_user_name` (`tenant_id`,`user_name`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_dept` (`tenant_id`,`dept_id`),
  KEY `idx_tenant_phone` (`tenant_id`,`phone`),
  KEY `idx_tenant_empno` (`tenant_id`,`emp_no`)
) ENGINE=InnoDB AUTO_INCREMENT=900015001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户(租户员工)';
/*!40101 SET character_set_client = @saved_cs_client */;

